# Intel newsroom post on MLPerf Inference v6.1, held against the v5.0, v5.1, v6.0 and v6.1 result files. python3 -I check_claims_intel_v61.py
import json,hashlib,re
FILES=['raw/inf_5.0.json','raw/inf_5.1.json','raw/inf_6.0.json','raw/inf_6.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
V5=json.loads(RAW[FILES[0]]); V51=json.loads(RAW[FILES[1]]); V0=json.loads(RAW[FILES[2]]); B=list(json.loads(RAW[FILES[3]]).values()); s=str; pc=lambda x,y:100*(x/y-1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
def b(org,sysn,m,sc):
    r=[x for x in B if x['Organization']==org and sysn in x['SystemName'] and x['Model']==m and x['Scenario']==sc and x['Division']=='closed']; assert len(r)==1,(org,sysn,m,sc,len(r)); return r[0]['Result']
def a(i,m,sc):
    r=[x for x in V0 if x['ID']==i and x['Model']==m and x['Scenario']==sc and x['Category']=='closed']; assert len(r)==1,(i,m,sc,len(r)); return r[0]['Performance_Result']
IP=[]
i1,i0=b('Intel','1-node-2S-GNR_128C','llama3_1-8b','Server'),a('6.0-0057','llama3.1-8b','Server'); j1,j0=b('Intel','1-node-2S-GNR_128C','llama3_1-8b','Offline'),a('6.0-0057','llama3.1-8b','Offline')
ok=(round(i1,2),round(i0,2),round(j1,2),round(j0,2))==(1139.51,471.54,1916.74,1229.56) and round(i1/i0,1)==2.4 and round(pc(j1,j0))==56
IP.append(mk('IP1','Intel Xeon 6980P processors delivered a 2.4x increase in Llama 3.1 8B Server throughput and a 56% increase in Offline throughput','Intel 1-node-2S-GNR_128C, v6.0 entry 6.0-0057 against the v6.1 entry, Llama 3.1 8B','2.4x Server (1,139.51 vs 471.54), +56% Offline (1,916.74 vs 1,229.56)',f'Server {i1:,.2f} against {i0:,.2f} ({i1/i0:.2f}x), Offline {j1:,.2f} against {j0:,.2f} ({pc(j1,j0):+.1f}%)','CONSISTENT' if ok else 'BELOW','The post says increase of 2.4x. The ratio is 2.42x, which is +142%.'))
isx=lambda h:'Xeon' in s(h)
def part0(L):
    return [x for x in L if x['Category']=='closed' and x['Submitter']!='Intel' and 'datacenter' in x['Suite'] and ((int(x['Total Accelerators'] or 0)==0 and isx(x['Processor'])) or 'Arc' in s(x['Accelerator']))]
def part1(L):
    return [x for x in L if x['Division']=='closed' and x['Organization']!='Intel' and x['SystemType']=='datacenter' and (((x['total_accelerators'] or 0)==0 and isx(x['host_processor_model_name'])) or 'Arc' in s(x['accelerator_model_name']))]
p0,p1=part0(V0),part1(B)
IP.append(mk('IP2','Customer and partner participation on Intel platforms also increased from 29 results in v6.0 to 39 in v6.1','closed datacenter rows not submitted by Intel with a Xeon host and no accelerator, or an Arc Pro accelerator, in the v6.0 and v6.1 files','29 results in v6.0, 39 in v6.1',f'v6.0 {len(p0)} rows ({len({x["ID"] for x in p0})} entries), v6.1 {len(p1)} rows ({len({(x["Organization"],x["SystemName"]) for x in p1})} entries)','CONSISTENT' if (len(p0),len(p1))==(29,39) else 'BELOW','Our rule follows the post footnote: Xeon as primary compute or Arc Pro as accelerator, Intel own submissions excluded. A result is one model and scenario row. The v6.1 count of 39 reproduces. In v6.0 five partners (Cisco, Dell, Lenovo, Quanta Cloud Technology, Supermicro) have four rows each, which is 20.'))
def cpuonly0(L,org): return [x for x in L if x['Submitter']==org and int(x.get('Total Accelerators') or x.get('a#') or 0)==0 and isx(x['Processor'])]
orc=[x for x in B if x['Organization']=='Oracle' and (x['total_accelerators'] or 0)==0]; rh=[x for x in B if x['Organization']=='RedHat_Intel']
prev_orc=sum(len(cpuonly0(L,'Oracle')) for L in (V5,V51,V0)); prev_rh=sum(len([x for x in L if 'RedHat' in x['Submitter'] and int(x.get('Total Accelerators') or x.get('a#') or 0)==0 and isx(x['Processor'])]) for L in (V5,V51,V0))
b70=lambda L,k:[x for x in L if 'B70' in s(x[k])]
qs=sorted({x['Organization'] for x in B if 'B70' in s(x['accelerator_model_name']) and x['Organization']!='Intel'}); prev70=sum(1 for x in V0 if 'B70' in s(x['Accelerator']) and x['Submitter']!='Intel')
IP.append(mk('IP3','Oracle contributed its first Intel-based submission; Red Hat delivered its first Xeon CPU inference submission, and Quanta Cloud Technology and Supermicro provided the first partner submissions using Intel Arc Pro B70','Oracle and Red Hat Xeon CPU-only entries and non-Intel Arc Pro B70 entries in v5.0, v5.1, v6.0 and v6.1','three firsts',f'Oracle Xeon CPU-only rows: v6.1 {len(orc)}, earlier {prev_orc}. RedHat_Intel rows: v6.1 {len(rh)}, earlier {prev_rh}. Non-Intel B70 submitters in v6.1: {qs}, in v6.0: {prev70}','CONSISTENT' if len(orc)>0 and prev_orc==0 and len(rh)>0 and prev_rh==0 and set(qs)=={"Quanta_Cloud_Technology","Supermicro"} and prev70==0 else 'BELOW','Intel-based for Oracle is read as a Xeon CPU-only entry. Oracle GPU systems with Intel hosts are not counted.'))
cpu=lambda L,k:[x for x in L if x['Division' if k==1 else 'Category']=='closed' and ((x['total_accelerators'] or 0)==0 if k==1 else int(x['Total Accelerators'] or 0)==0) and 'datacenter' in (x['SystemType'] if k==1 else x['Suite'])]
c0,c1=cpu(V0,0),cpu(B,1); sku0=sorted({s(x['Processor']) for x in c0}); sku1=sorted({s(x['host_processor_model_name']) for x in c1})
IP.append(mk('IP4','Intel broadened its Xeon participation in MLPerf v6.1 from two benchmarked Xeon 6 SKUs in v6.0 to five, increasing the number of CPU inference results from 24 to 35','closed datacenter rows with no accelerator, v6.0 and v6.1, by processor model','two SKUs to five, 24 to 35 results',f'v6.0: {len(c0)} rows, {len(sku0)} processor models. v6.1: {len(c1)} rows, {len(sku1)} processor models ({", ".join(sku1)})','CONSISTENT' if (len(c0),len(c1))==(24,35) else 'BELOW','Counting all submitters. The two SKU and five SKU counts reproduce for Intel own entries. The v6.1 file holds 33 CPU rows, not 35.'))
vend=sorted({('Intel' if 'Intel' in s(x['host_processor_model_name']) else s(x['host_processor_model_name'])[:20]) for x in c1}|{('Intel' if 'Intel' in s(x['Processor']) else s(x['Processor'])[:20]) for x in c0})
IP.append(mk('IP5','Intel Xeon remains the only standalone server CPU represented in MLPerf Inference submissions','closed datacenter rows with no accelerator, v6.0 and v6.1, host processor vendor','Xeon is the only standalone server CPU',f'processor vendors in CPU-only rows: {vend}','CONSISTENT' if vend==['Intel'] else 'BELOW','Read for the v6.0 and v6.1 files only.'))
mods=sorted({x['Model'] for x in B if x['Organization']=='Intel' and 'B70' in s(x['accelerator_model_name'])}); one=[x for x in B if x['Organization']=='Intel' and 'B70' in s(x['accelerator_model_name'])][0]
IP.append(mk('IP6','A single node configured with four Intel Arc Pro B70 GPUs provides 128GB of VRAM and supported submissions across Llama 3.1 8B, Llama 2 70B, gpt-oss-120B, Whisper and end-to-end retrieval-augmented generation (E2E-RAG)','Intel four B70 entries in the v6.1 file; 4 times 32GB per the post footnote','four GPUs, 128GB, five model families',f'{one["total_accelerators"]} accelerators; models {mods}; 4 x 32 = 128 GB','CONSISTENT' if one['total_accelerators']==4 and {m for m in mods if m.startswith(("llama3","llama2","gpt","whisper"))} and any(m.startswith('e2e-rag') for m in mods) and len(mods)==6 else 'BELOW','The file splits E2E-RAG into two model names, database and question answering. The 32GB per card is from the post footnote, not a file field.'))
q1,q2,q10,q20=b('Intel','1-node-4x-BMG-B70','gpt-oss-120b','Server'),b('Intel','1-node-4x-BMG-B70','gpt-oss-120b','Offline'),a('6.0-0101','gpt-oss-120b','Server'),a('6.0-0101','gpt-oss-120b','Offline')
IP.append(mk('IP7','On the same four-GPU system used in v6.0, gpt-oss-120B Server performance improved 36%, while Offline performance increased 27%','Intel 4 x Arc Pro B70 entry, v6.0 entry 6.0-0101 against the v6.1 entry, gpt-oss-120B','+36% Server (1,296.87 vs 951.67), +27% Offline (1,956.40 vs 1,536.90)',f'Server {q10:,.2f} to {q1:,.2f} ({pc(q1,q10):+.1f}%). Offline {q20:,.2f} to {q2:,.2f} ({pc(q2,q20):+.1f}%)','CONSISTENT' if (round(q1,2),round(q10,2),round(q2,2),round(q20,2))==(1296.87,951.67,1956.40,1536.90) else 'BELOW',''))
rg=[x for x in B if 'rag' in x['Model'].lower()]
IP.append(mk('IP8','In a single measured run on a system combining an Intel Xeon 6787P processor with four Intel Arc Pro B70 GPUs','v6.1 E2E-RAG entries','Xeon 6787P with four Arc Pro B70',f'{len(rg)} E2E-RAG rows: '+', '.join(f'{x["Organization"]} {x["SystemName"]} {x["host_processor_model_name"]} {x["total_accelerators"]} accelerators {x["Model"]}' for x in rg),'CONSISTENT' if rg and all('6787P' in s(x['host_processor_model_name']) and x['total_accelerators']==4 for x in rg) else 'BELOW',''))
c6=[x for x in B if x['Organization']=='Intel' and '6980P' in s(x['host_processor_model_name'])][0]; c9=[x for x in B if x['Organization']=='Intel' and '698X' in s(x['host_processor_model_name'])][0]
IP.append(mk('IP9','Configuration lines in footnotes 1 and 3 of the post','Intel entries in the v6.1 file, host processor fields','2x Xeon 6980P with 128 cores each, no accelerator; 1x Xeon 698X with 86 cores and 4x Arc Pro B70',f'{c6["host_processors_per_node"]}x {c6["host_processor_model_name"]}, {c6["host_processor_core_count"]} cores, {c6["total_accelerators"]} accelerators; {c9["host_processors_per_node"]}x {c9["host_processor_model_name"]}, {c9["host_processor_core_count"]} cores, {c9["total_accelerators"]} accelerators','CONSISTENT' if tuple(int(v) for v in (c6['host_processors_per_node'],c6['host_processor_core_count'],c9['host_processors_per_node'],c9['host_processor_core_count'],c9['total_accelerators']))==(2,128,1,86,4) else 'BELOW',''))
json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=IP),open('claims_intel_v61.json','w'),indent=1)
for c in IP: print(c['id'],c['outcome'],'|',c['stated'][:48],'|',c['delivered'][:250])
